from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    background = counts.most_common(1)[0][0]
    candidates = [v for v in counts if v not in (0, background)]
    if not candidates:
        return [row[:] for row in grid]
    color = min(candidates, key=lambda v: counts[v])

    points = [(r, c) for r in range(h) for c in range(w)
              if grid[r][c] == color]
    rmin = min(r for r, c in points)
    rmax = max(r for r, c in points)
    cmin = min(c for r, c in points)
    cmax = max(c for r, c in points)
    shape = {(r-rmin, c-cmin) for r, c in points}
    sh, sw = rmax-rmin+1, cmax-cmin+1
    context = {(r, c): grid[rmin+r][cmin+c]
               for r in range(sh) for c in range(sw)
               if (r, c) not in shape}

    out = [row[:] for row in grid]
    for top in range(h-sh+1):
        for left in range(w-sw+1):
            if (all(grid[top+r][left+c] == value
                    for (r, c), value in context.items())
                and all(grid[top+r][left+c] == 0 for r, c in shape)):
                for r, c in shape:
                    out[top+r][left+c] = color
    return out
